stage_progress_util = {}

--- 스테이지 Custom Data를 가져옴
--- @param key number Custom Data의 Key
--- @param default_value boolean 해당 Key에 해당하는 Custom Data가 없을 경우 가져오는 기본 값
function stage_progress_util.get_custom_data(key, default_value)
	default_value = lua_helper.get_or_default(default_value, false)

	return stage_progress:GetCustomData(key, default_value)
end

--- 스테이지 Custom Data를 가져옴
--- @param key number Custom Data의 Key
--- @param default_value number 해당 Key에 해당하는 Custom Data가 없을 경우 가져오는 기본 값
function stage_progress_util.get_custom_data_int(key, default_value)
	default_value = lua_helper.get_or_default(default_value, 0)

	return stage_progress:GetCustomDataInt(key, default_value)
end

--- 스테이지 Custom Data를 설정
--- @param key number Custom Data의 Key
--- @param value any 설정 할 Custom Data의 값
function stage_progress_util.set_custom_data(key, value)
	stage_progress:SendCustomData(key, value)
end

function stage_progress_util.set_custom_data_async(key, value)
	coroutine.yield(stage_progress:SendCustomDataAsync(key, value))
end

function stage_progress_util.has_star_piece(key_name)
	return stage_progress:HasStarPiece(key_name)
end


return {
	create = function()
		return stage_progress_util
	end
}

