local string_helper = {}

function string_helper.start_with(str, start)
    return str:sub(1, #start) == start
end

function string_helper.ends_with(str, ending)
    return ending == "" or str:sub(-(#ending)) == ending
end

function string_helper.is_nil_or_empty(str)
    return str == nil or str == ""
end

return {
    create = function()
        return string_helper
    end
}

1123:
-- 타임라인과 통신하기 위해 준비된 테이블
-- 타임라인 테이블에는 액션(루아 함수)을 등록 할 수 있다
timeline_table = { actions = { } }

-- name은 무조건 string 타입을 사용 해야 된다.
function timeline_table.register_action(name, func, handler)
	timeline_table.actions[name] = { func = func, handler = handler }
end

function timeline_table.unregister_action(name)
	timeline_table.actions[name] = nil
end

function timeline_table.execute_action(name, param_a, param_b, param_c)
	local action = timeline_table.actions[name].func
	local handler = timeline_table.actions[name].handler

	if action ~= nil then
		action(handler, param_a, param_b, param_c)
	end
end

function timeline_table.get_action_coroutine(name, param_a, param_b, param_c)
	local action = timeline_table.actions[name].func
	local handler = timeline_table.actions[name].handler

	if action ~= nil then
		return util.cs_generator(action, handler, param_a, param_b, param_c)
	end

	return nil
end

function timeline_table.clear_actions()
	timeline_table.actions = { }
end

function timeline_table.dispose()
	timeline_table.actions = nil
end

return {
	create = function()
		return timeline_table
	end
}

