user_util = {}

--- 남기사를 가지고 있는지 여부를 반환해주는 함수
function user_util.has_knight_male()
    return user:GetCharacter(CS.Oak.CharacterSpecId.KnightMale, true) ~= nil
end

--- 중국의 챔피언인 페이 캐릭터를 가지고있는지 여부를 반환해주는 함수
function user_util.has_fei()
    return user:GetCharacter(CS.Oak.CharacterSpecId.ChinaHeroBoy, true) ~= nil
end

--- 주인공 기사 캐릭터를 가져온다.
---@param female_name string
---@param male_name string
function user_util.get_knight_character(female_name, male_name)
    if user_util.has_knight_male() then
        return get_character(male_name)
    end

    return get_character(female_name)
end

--- 중국영웅(선산권사 페이,메이) 캐릭터를 가져온다.(남,여 둘중에 하나만 얻을수 있음)
---@param fei_name string
---@param mei_name string
function user_util.get_china_hero_character(fei_name, mei_name)
    if user_util.has_fei() then
        return get_character(fei_name)
    end

    return get_character(mei_name)
end

return {
    create = function()
        return user_util
    end
}

