	local spec = lua_helper.get_value(data, 'spec')
	local id =  lua_helper.get_value(data, 'id')
	local exp = lua_helper.get_value(data, 'exp')
	local level = lua_helper.get_value(data, 'level', stage.Spec.StageStandardLevel)
	local amount = lua_helper.get_value(data, 'amount')
	local elemental = weapon_util.get_elmental_from_str(lua_helper.get_value(data, 'elemental', 'none'))

	return CS.Oak.Weapon.CreateMonsterWeapon(spec, id, exp, level, amount, elemental)
end

return {
	create = function()
		return weapon_util
	end
}

