	}

	self.post_story_section = quest_util.load_section(self, 'DemonWorldAdulteryPostSection')
end

function local_class:on_load_resource_routine()
	yield_return_func(quest_util.load_pool_resource, 'fx_adultery_camera_target', 'FX_get')

	self.resholder = CS.Foundations.ResourceHolder()
	yield_return_func(CS.Foundations.IResourceHolderExtensions.LoadPrefabAsync,
			self.resholder, 'ondemand/v2_15_demonworld/effects', 'camera_pointer', function(prefab)
				self.picturing_infos.pointer = CS.UnityEngine.GameObject.Instantiate(prefab)
				self.picturing_infos.pointer.transform.position = unity_class.vector3.zero
				self.picturing_infos.pointer:SetActive(false)
			end)

	CS.Oak.CommonScreenplay.PreloadTutorialSpine()
end

function local_class:on_event(e)
	return quest_util.on_event(self, e)
end

function local_class:on_joypad_event(e)
	if lua_helper.reference_equals(e.JoypadEventType, CS.Oak.JoypadEventType.StickDirection)
			and self.picturing_infos.current_state == self.picturing_infos.state.camera_enabled then
		self:move_camera(e.StickDirection, self.picturing_infos.current_zone_key)
		return true
	end

	return false
end

function local_class:on_touch_event(e)
	if e.TouchEventType == CS.Oak.TouchEventType.Action1TouchDown
			and self.picturing_infos.current_state == self.picturing_infos.state.camera_enabled then
		self.picturing_infos.current_state = self.picturing_infos.state.taking_picture
		coroutine_manager:StartCoroutine(stage.StageGameObject, util.cs_generator(self.take_picture, self,
				self.picturing_infos.current_zone_key))
		return true
	end

	return false
end

function local_class:on_exclusive_quest_start_event(e)
	if e.Key ~= self.exclusive_quest_event_key then
		self.exclusive_on = true
		return true
	end

	return false
end

function local_class:on_exclusive_quest_end_event(e)
	if e.Key ~= self.exclusive_quest_event_key then
		self.exclusive_on = false
		return true
	end

	return false
end

function local_class:on_stage_loaded()
	local target_infos = self.target_follow_infos.target_infos
	target_infos.male = self.get_male_target()
	target_infos.female = self.get_female_target()

	field_ui_manager:RemoveUI(target_infos.male, CS.Oak.FieldUiType.CharacterStats)
	field_ui_manager:RemoveUI(target_infos.female, CS.Oak.FieldUiType.CharacterStats)

	-- 타겟 웨이포인트 위치값 캐싱
	for area_name, _ in pairs(self.target_follow_infos.area_infos) do
		local area_info = self.target_follow_infos.area_infos[area_name]

		for i = 1, #area_info.move_infos do
			local move_info = area_info.move_infos[i]

			if move_info.wp_nums ~= nil then
				move_info.target_pos_list = {}

				for j = 1, #area_info.groups do
					move_info.target_pos_list[j] = {}

					for k = 1, #move_info.wp_nums[j] do
						move_info.target_pos_list[j][k] = self.get_target_move_pos(
								area_info.route_num, j, move_info.wp_nums[j][k])
					end
				end
			end
		end
	end

	for area_key, _ in pairs(self.picturing_infos.zone_infos) do
		local zone_info = self.picturing_infos.zone_infos[area_key]
		for key, _ in pairs(zone_info) do
			local bounds_info =  zone_info[key]
			bounds_info.bounds = field:GetZone(bounds_info.name).Bounds
		end
	end

	self.picturing_infos.camera_info.pivot_tf = stage_camera.transform.parent
	self.picturing_infos.camera_info.cam_half_height = stage_camera.Size
	self.picturing_infos.camera_info.cam_half_width = stage_camera.HalfWidth

	self.main_quest = user_progress:GetStartedQuest(self.main_quest_id)

	local constants = require('minigame/DemonWorldBasicSystem/DemonWorldCivilianConstants')
	local bgs = constants[stage.Name].battle_group_names
	for _, battle_group_name in pairs(bgs) do
		table.insert(self.battle_groups, stage.BattleManager:GetBattleGroup(battle_group_name))
	end
end

function local_class:load_progress()
	return util.cs_generator(quest_util.load_progress, self)
end

function local_class:dispose()
	quest_util.dispose_controller(self)
	message_system:Unsubscribe(self, typeof(CS.Oak.JoypadEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.TouchEvent))

	if self.current_section ~= nil then
		self.current_section:exit()
		self.current_section = nil
	end

	if self.pre_story_section ~= nil then
		self.pre_story_section = nil
	end

	if self.post_story_section ~= nil then
		self.post_story_section = nil
	end

	self.cs_controller = nil
	self.quest_progress = nil
	self.quest_spec = nil
	self.scene = nil

	self.sections = nil
	self.inter_section_params = nil

	if self.ring_item ~= nil then
		self.ring_item:ConsumeComplete()
		self.ring_item = nil
	end

	if is_unity_null(self.picturing_infos.pointer) == false then
		CS.UnityEngine.Object.Destroy(self.picturing_infos.pointer)
		self.picturing_infos.pointer = nil
	end

	if self.resholder ~= nil then
		self.resholder:Dispose()
		self.resholder = nil
	end

	self:dispose_fx_camera_target()
	self.target_follow_infos = nil
	self.picturing_infos = nil
	self.dollar_ui = nil
	self.battle_groups = nil
end

--region 타겟 추적 이벤트
function local_class:start_target_follow(key)
	coroutine_manager:StartCoroutine(stage.StageGameObject, util.cs_generator(self.target_follow_routine, self, key))
end

function local_class:stop_target_follow()
	self.target_follow_infos.current_end_state = self.target_follow_infos.follow_end_state.force_stop
end

function local_class:target_follow_routine(key)
	local area_info = self.target_follow_infos.area_infos[key]
	local groups = {}
	local targets = {}
	local leader = user_party.Leader
	local leader_tf = leader.Transform

	local changing_state = {
		none = 0,
		changed = 1,
		pre_setting = 2,
	}
	local state_done_count = 0
	local time_passed = 0
	local move_infos = area_info.move_infos
	local move_info_index = 1
	local current_changing_state = changing_state.pre_setting

	self.target_follow_infos.current_end_state = self.target_follow_infos.follow_end_state.none

	--region 노티스 관련 변수
	local notice_state = self.target_follow_infos.notice_infos.state
	local current_emoticon = nil
	local notice_time_passed = 0
	local current_notice_state = notice_state.idle
	local emoticon_infos = self.target_follow_infos.emoticon_infos
	--endregion

	for i = 1, #area_info.groups do
		local target = self.target_follow_infos.target_infos[area_info.groups[i]]
		groups[i] = {
			fo = target,
			transform = target.Transform,
			progress_index = 1,
			state_done = false,
		}
		targets[i] = groups[i].fo
		groups[i].fo.ActiveState = active_state('visible')
	end

	local view_unit_bounds = CS.UnityEngine.Bounds(vector(0, 0, 0), unity_class.vector3.one * 0.05)

	while self.target_follow_infos.current_end_state == self.target_follow_infos.follow_end_state.none do
		local delta_time = unity_class.time.deltaTime
		local dist_target = groups[1].fo
		local to_leader_vec = leader_tf.position - dist_target.transform.position
		local dist_to_player = to_leader_vec.magnitude

		local wall_blocking = false
		view_unit_bounds.center = groups[1].transform.position + vector(0, 0.5, 0)
		local obj_list = CS.Oak.LuaCollisionUtil.GetFieldObjectsCollidedBy(view_unit_bounds, to_leader_vec)
		for i = 0, obj_list.Count - 1 do
			local obj = obj_list[i]
			if lua_helper.type_compare(obj, CS.Oak.Character) == false then
				wall_blocking = true
				break
			end
		end
		obj_list:Dispose()

		-- 타겟이 플레이어를 인식한 경우
		if current_notice_state ~= notice_state.idle and current_notice_state ~= notice_state.cooldown then
			if current_notice_state == notice_state.question then
				if notice_time_passed == 0 then
					current_emoticon = character_util.show_emoticon_with_data(groups[1].fo,nil,
							'question', nil, {emoticon_time = emoticon_infos.emoticon_time})
					notice_time_passed = notice_time_passed + delta_time

				elseif notice_time_passed > emoticon_infos.duration then
					current_notice_state = notice_state.silence
					notice_time_passed = 0
					current_emoticon = nil
					music_player_util.play_sfx({sfx_name = '01_rustle_01', parent = groups[1].fo,
												type_priority = 'event', player_priority = 'npc'})
				else
					notice_time_passed = notice_time_passed + delta_time
				end

			elseif current_notice_state == notice_state.silence then
				-- 서로 눈이 마주쳤을 때
				if wall_blocking == false then
					character_util.look_at(groups[1].fo, leader)
				end

				if groups[1].fo.Direction == direction_util.get_opposite(leader.Direction)
						and wall_blocking == false then
					-- 실패
					self.target_follow_infos.current_end_state = self.target_follow_infos.follow_end_state.detected

				else
					if notice_time_passed == 0 then
						current_emoticon = character_util.show_emoticon_with_data(groups[1].fo,
								nil, 'silence', nil,
								{emoticon_time = emoticon_infos.emoticon_time})
						notice_time_passed = notice_time_passed + delta_time
						character_util.look_at(groups[1].fo, leader)

					elseif notice_time_passed > emoticon_infos.duration then
						current_emoticon = nil
						current_notice_state = notice_state.cooldown
						notice_time_passed = 0

						-- 다음 프레임에 리셋되도록 함
						current_changing_state = changing_state.pre_setting
						time_passed = 0

					else
						notice_time_passed = notice_time_passed + delta_time
					end
				end
			end

		else
			-- 다시 인식하기 전까지 쿨타임 부여
			if current_notice_state == notice_state.cooldown then
				if notice_time_passed < self.target_follow_infos.notice_infos.notice_cooltime then
					notice_time_passed = notice_time_passed + delta_time
				else
					notice_time_passed = 0
					current_notice_state = notice_state.idle
				end
			end

			-- 전반적인 타겟 행동 구성
			local current_move_info = move_infos[move_info_index]

			if current_move_info.state == 'stop' then
				if current_changing_state == changing_state.pre_setting then
					for i = 1, #groups do
						character_util.remove_anim_and_emotion(groups[i].fo)
						groups[i].fo.Direction = current_move_info.directions[i]
					end
					current_changing_state = changing_state.none
				end

				if time_passed < current_move_info.duration then
					time_passed = time_passed + delta_time
				else
					time_passed = 0
					current_changing_state = changing_state.changed
				end

			elseif current_move_info.state == 'talking' then
				if current_changing_state == changing_state.pre_setting then
					for i = 1, #groups do
						-- 2인이 아닌 경우 talking 스테이트에 해당되는 데이터를 넣지 않을 것이므로 추가 조건문이 필요 없음
						local look_target = groups[i % #groups + 1].fo
						character_util.look_at(groups[i].fo, look_target)

						character_util.set_anim(groups[i].fo,
								{name = current_move_info.anim_emo_data[i].anim})
						character_util.set_emotion(groups[i].fo,
								{name = current_move_info.anim_emo_data[i].emotion})
					end

					current_changing_state = changing_state.none
				end

				if time_passed < current_move_info.duration then
					time_passed = time_passed + delta_time
				else
					time_passed = 0
					current_changing_state = changing_state.changed
				end

			elseif current_move_info.state == 'walk' then
				--[[
					각 타겟별로 이동 루틴 진행
					짧은 Waypoint의 경우 한 프레임에 여러 지점을 지날 수 있기 때문에
					이전 계산에 남은만큼 계속 추가적으로 움직여 줌
				]]

				if current_changing_state == changing_state.pre_setting then
					for i = 1, #groups do
						character_util.set_anim(groups[i].fo, self:get_move_anim_data(current_move_info.speed))
					end
					current_changing_state = changing_state.none
				end

				for i = 1, #groups do
					if groups[i].state_done == false then
						local move_done = false
						local move_dist = current_move_info.speed * delta_time

						while move_done == false do
							local pass_waypoint, dist_left = self:target_fo_move(groups[i].fo, groups[i].transform,
									current_move_info.target_pos_list[i][groups[i].progress_index],
									move_dist, current_move_info.speed)

							if pass_waypoint then
								-- 해당 스테이트의 모든 Waypoint를 지났을 때
								if groups[i].progress_index >= #current_move_info.target_pos_list[i] then
									groups[i].state_done = true
									state_done_count = state_done_count + 1
									move_done = true
								else
									-- 남은 거리 재할당
									move_dist = dist_left
									groups[i].progress_index = groups[i].progress_index + 1
								end
							else
								move_done = true
							end
						end
					end
				end

				-- 모든 타겟들의 이동이 끝났을 때
				if state_done_count == #groups then
					current_changing_state = changing_state.changed
				end

			elseif current_move_info.state == 'look_around' then
				if current_changing_state == changing_state.pre_setting then
					current_changing_state = changing_state.none
				end

				for i = 1, #groups do
					if time_passed < current_move_info.dir_delay then
						local target_dir = current_move_info.dir_list[i][groups[i].progress_index]
						if target_dir ~= groups[i].fo.Direction then
							music_player_util.play_sfx({sfx_name = '01_swing_01', parent = groups[i].fo,
														type_priority = 'event', player_priority = 'npc'})
							groups[i].fo.Direction = current_move_info.dir_list[i][groups[i].progress_index]
						end
						time_passed = time_passed + delta_time

						-- 바라보는 방향에 플레이어가 있고, 플레이어도 타겟을 바라보고 있을 때
						if groups[i].fo.Direction == vector_util.to_direction(
								leader_tf.position - groups[i].transform.position)
								and groups[i].fo.Direction == direction_util.get_opposite(leader.Direction)
								and wall_blocking == false then
							current_notice_state = notice_state.question
							notice_time_passed = 0
						end
					else
						time_passed = 0
						groups[i].progress_index = groups[i].progress_index + 1

						if groups[i].progress_index > #current_move_info.dir_list[i] then
							groups[i].state_done = true
							state_done_count = state_done_count + 1
						end
					end
				end

				if state_done_count == #groups then
					current_changing_state = changing_state.changed
				end
			end

			if current_changing_state == changing_state.changed then
				-- 스테이트 전환
				-- 다음 프레임에 적용됨
				move_info_index = move_info_index + 1
				current_changing_state = changing_state.pre_setting

				state_done_count = 0

				for i = 1, #groups do
					groups[i].state_done = false
					groups[i].progress_index = 1
					character_util.remove_anim_and_emotion(groups[i].fo)
				end

				if move_info_index > #move_infos then
					self.target_follow_infos.current_end_state = self.target_follow_infos.follow_end_state.success
				end
			end
		end

		-- 거리 체크
		if self.target_follow_infos.current_end_state == self.target_follow_infos.follow_end_state.none then
			-- 남편 중심으로 거리 체크

			if dist_to_player < 1 and wall_blocking == false then
				-- 너무 가까이 있는 경우 즉시 걸림
				self.target_follow_infos.current_end_state = self.target_follow_infos.follow_end_state.detected

			elseif dist_to_player < 2 and wall_blocking == false then
				-- 의심 단계
				if current_notice_state == notice_state.idle then
					current_notice_state = notice_state.question
					for i = 1, #groups do
						character_util.remove_anim_and_emotion(groups[i].fo)
					end
					notice_time_passed = 0
				end

			elseif dist_to_player > 9 then
				self.target_follow_infos.current_end_state = self.target_follow_infos.follow_end_state.failed
			end
		end

		coroutine.yield()
	end

	if current_emoticon ~= nil then
		current_emoticon:Dispose()
		current_emoticon = nil
	end

	if self.target_follow_infos.current_end_state == self.target_follow_infos.follow_end_state.detected then
		-- 들켜서 실패
		self:detected_target_follow(key, targets)
	elseif self.target_follow_infos.current_end_state == self.target_follow_infos.follow_end_state.failed then
		-- 멀어져서 실패
		self:failed_target_follow(key, targets, true)
	elseif self.target_follow_infos.current_end_state == self.target_follow_infos.follow_end_state.success then
		-- 추적 성공
		self:send_cse_to_section('success')
	end
end

function local_class:failed_target_follow(key, targets, in_controller)
	field_ui_manager:Hide()
	party_util.stop_and_disable_control()

	if in_controller then
		-- 실패 연출
		for _, target in pairs(targets) do
			character_util.spine_set_alpha_fade(target, 0, 1)
		end
	end

	if targets[1].Position.x < user_party.Leader.Position.x then
		user_party.Leader.Direction = CS.Oak.Direction.Left
	else
		user_party.Leader.Direction = CS.Oak.Direction.Right
	end

	character_util.set_emotion(user_party.Leader, {name = 'tired'})
	character_util.set_anim(user_party.Leader, {name = 'seat'})
	music_player_util.play_sfx_one_shot('03_dialogue_sadness_01')

	wait_for_sec(1.1)

	self:try_give_up_target_follow(key, targets, false, in_controller)
end

function local_class:detected_target_follow(key, targets)
	field_ui_manager:Hide()
	party_util.stop_and_disable_control()

	-- 실패 연출
	for _, target in pairs(targets) do
		character_util.look_at(target, user_party.Leader)
		character_util.set_emotion(target, {name = 'attack'})
	end

	music_player_util.play_sfx_one_shot('03_runaway_01')
	party_util.look_at(targets[1])
	party_util.set_anim({name = 'embarrassed'})
	party_util.set_emotion({name = 'surprise'})

	--이봐, 너 뭐하는 녀석이야?
	music_player_util.play_sfx_one_shot('03_dialogue_negative_01')
	speech_bubble_util.show_speech_bubble_async(targets[1],
			{key = 'demonworld_adultery_31', skip = true, bubble_type = 'shout'})

	self:try_give_up_target_follow(key, targets, true, true)
end

function local_class:try_give_up_target_follow(key, targets, detected, in_controller)
	--미행을 들켰다.. / 타겟을 놓쳤다..
	stage.FieldUINarrationBox:Show()
	yield_return(stage.FieldUINarrationBox, 'SetNarration',
			game_string:GetString(detected and 'demonworld_adultery_31_1' or 'demonworld_adultery_31_2'), 0, 0)

	--재도전 한다. (진행 재개)
	--포기한다. (현 위치에서 자유 진행, 퀘스트 원점)
	local result = choose_util.play_choose_event({
		{'demonworld_adultery_32', 'mercy'},
		{'demonworld_adultery_33', 'brutal'}
	})

	yield_return(stage.FieldUINarrationBox, 'HideAnimation')

	if result == 1 then
		-- 재도전
		screen_util.fade_out_async(1, unity_class.color.black, 'linear')

		if in_controller then
			for _, target in pairs(targets) do
				character_util.remove_anim_and_emotion(target)
				character_util.spine_set_alpha_fade(target, 1, 0)
			end
		end

		party_util.remove_emotion()
		party_util.remove_animation()

		self:send_cse_to_section('restart')
		return
	else
		if key ~= 'phase_1' then
			music_player_util.play_stage_music({state = 'field', mix = 2.0})
		end
		screen_util.fade_out_async(1, unity_class.color.black, 'linear')

		party_util.remove_emotion()
		party_util.remove_animation()

		self:send_cse_to_section('give_up')
	end
end

function local_class:send_cse_to_section(...)
	local str_list = { self.target_follow_infos.cse_send_key }
	local args = { ... }
	for _, str in pairs(args) do
		table.insert(str_list, str)
	end

	local cse = CS.Oak.CustomStageEvent.Create(user_party.Leader, str_list)
	self:on_event(cse)
	cse:Dispose()
end

-- (웨이포인트에 도달했는지, 이번 이동에 남은 거리)를 반환함
function local_class:target_fo_move(fo, transform, target_pos, move_dist, move_speed)
	local start_pos = transform.position
	local to_target_vec = target_pos - start_pos
	local to_target_dist = to_target_vec.magnitude
	local target_dir = vector_util.to_direction(to_target_vec)

	-- 방향이 바뀌었을 때에만 갱신함
	if target_dir ~= fo.Direction then
		character_util.remove_anim(fo)
		fo.Direction = target_dir
		character_util.set_anim(fo, self:get_move_anim_data(move_speed))
	end

	if to_target_dist > move_dist then
		fo.Position = start_pos + to_target_vec.normalized * move_dist
		return false, 0
	else
		fo.Position = target_pos
		return true, move_dist - to_target_dist
	end
end

function local_class:get_move_anim_data(move_speed)
	if move_speed > 5.5 then
		return {name = 'run', scale = move_speed / 7}
	else
		return {name = 'walk', scale = move_speed / 4}
	end
end

