--region 카메라 촬영
-- 각 섹션에서 호출할 것이므로 current_zone_key 세팅도 겸함
function local_class:activate_camera(key, reactivate)
	self.picturing_infos.current_state = self.picturing_infos.state.active_camera
	self.picturing_infos.current_zone_key = key

	if not reactivate then
		music_player_util.play_sfx_one_shot('01_camera_focus_01')
	end

	-- 세팅
	party_util.reset_controllers()

	-- 이동 불가 설정
	local manual_touch_state = user_party.Leader.FieldObjectController.CurrentState

	if manual_touch_state ~= nil
			and lua_helper.type_compare(manual_touch_state, CS.Oak.CharacterControllerManualTouchState) then
		manual_touch_state:RequestDisableControl(user_party.Leader, CS.Oak.DisabledControls.All)
	end

	coroutine.yield(nil)

	field_ui_manager:Show()

	-- 불필요한 UI 끔
	stage.FieldUIMiniMap:Hide()

	field_ui_manager:HideTargetUI(CS.Oak.FieldUiType.PartyState | CS.Oak.FieldUiType.ClassButton
			| CS.Oak.FieldUiType.TeamCombinationButton | CS.Oak.FieldUiType.SkillButton
			| CS.Oak.FieldUiType.ModeChangeButton | CS.Oak.FieldUiType.RoleButton)

	if CS.Oak.UI.NavigationBar.Instance ~= nil then
		CS.Oak.UI.NavigationBar.Instance:Hide()
	end

	local dollar_ui = self:get_dollar_ui()
	local dollar_ui_tf = dollar_ui.transform
	local ui_origin_pos = dollar_ui_tf.localPosition
	dollar_ui_tf.localPosition = vector(-999, 0, 0)
	while dollar_ui.activeSelf == false do
		coroutine.yield()
	end
	dollar_ui_tf.localPosition = ui_origin_pos
	dollar_ui:SetActive(false)

	-- 액션 버튼 이미지 변경
	field_ui_manager:GetSingleUI(CS.Oak.FieldUiType.ActionButton)
					.OverridenButtonAction = CS.Oak.CharacterControllerManualTouchState.Button1Action.Interact

	-- 카메라 포인터 활성화
	self.picturing_infos.pointer.transform.position = self.picturing_infos.camera_info.pivot_tf.position
	self.picturing_infos.pointer:SetActive(true)

	self:set_fx_camera_target(self.picturing_infos.zone_infos[key].success.bounds.center)

	message_system:Subscribe(self, typeof(CS.Oak.JoypadEvent), 'on_joypad_event')
	message_system:Subscribe(self, typeof(CS.Oak.TouchEvent), 'on_touch_event')

	self.picturing_infos.current_state = self.picturing_infos.state.camera_enabled
end

function local_class:move_camera(move_dir, key)
	local cam_info = self.picturing_infos.camera_info
	local move_diff = move_dir * unity_class.time.unscaledDeltaTime * cam_info.cam_move_speed
	local cur_pos = cam_info.pivot_tf.position + move_diff
	local pic_bounds = self.picturing_infos.zone_infos[key].boundary.bounds

	local cam_min_x = cur_pos.x - cam_info.cam_half_width
	local cam_max_x = cur_pos.x + cam_info.cam_half_width
	local cam_min_z = cur_pos.z - cam_info.cam_half_height
	local cam_max_z = cur_pos.z + cam_info.cam_half_height

	-- 카메라 범위가 사진 찍을 수 있는 존에 포함될 때
	if cam_min_x >= pic_bounds.min.x and cam_max_x <= pic_bounds.max.x
			and cam_min_z >= pic_bounds.min.z and cam_max_z <= pic_bounds.max.z then
		cam_info.pivot_tf.position = cur_pos
		self.picturing_infos.pointer.transform.localPosition = cur_pos
	end
end

function local_class:take_picture(key)
	message_system:Unsubscribe(self, typeof(CS.Oak.JoypadEvent))
	message_system:Unsubscribe(self, typeof(CS.Oak.TouchEvent))
	party_util.stop_and_disable_control()

	local success_bounds = self.picturing_infos.zone_infos[key].success.bounds
	local cam_pivot_tf = self.picturing_infos.camera_info.pivot_tf

	-- success
	local success = success_bounds:Contains(cam_pivot_tf.position)

	self:dispose_fx_camera_target()

	music_player_util.play_sfx_one_shot('01_shutter_02')

	time_util.mod(key, 0)

	screen_util.fade_out_async(0.1, unity_class.color.white, 'linear')

	field_ui_manager:Hide()

	self.picturing_infos.pointer:SetActive(false)

	self:activate_black_and_white(0)

	wait_for_unscaled_sec(0.3)

	screen_util.fade_in_async(0.1, unity_class.color.white, 'linear')

	wait_for_unscaled_sec(0.3)

	if success then
		yield_return_func(CS.Oak.CommonScreenplay.QTEComplete, 1.5)

		time_util.unmod(key)

		local cam_move_dist = (cam_pivot_tf.position - user_party.Leader.Position).magnitude
		local cam_reset_speed = 8
		local cam_reset_dur = cam_move_dist / cam_reset_speed

		camera_util.move(user_party.Leader.Position, cam_reset_dur, {end_target = user_party.Leader})
		self:deactivate_black_and_white(cam_reset_dur)

		-- 액션 버튼 복구
		field_ui_manager:GetSingleUI(CS.Oak.FieldUiType.ActionButton).OverridenButtonAction = nil

		local cse = CS.Oak.CustomStageEvent.Create(user_party.Leader, {self.picturing_infos.cse_send_key})
		self:on_event(cse)
		cse:Dispose()

	else
		wait_for_unscaled_sec(1)

		time_util.unmod(key)

		self:deactivate_black_and_white(1)

		-- 카메라 다시 켜줌
		self:activate_camera(key, true)
	end
end

function local_class:show_hidden_ui()
	field_ui_manager:ShowTargetUI(CS.Oak.FieldUiType.PartyState | CS.Oak.FieldUiType.ClassButton
			| CS.Oak.FieldUiType.TeamCombinationButton | CS.Oak.FieldUiType.SkillButton
			| CS.Oak.FieldUiType.ModeChangeButton | CS.Oak.FieldUiType.RoleButton)
end

function local_class:set_fx_camera_target(position)
	self:dispose_fx_camera_target()
	self.picturing_infos.fx_target = self.get_fx_camera_target():Instantiate(position)
end

function local_class:dispose_fx_camera_target()
	if not is_unity_null(self.picturing_infos.fx_target) then
		self.picturing_infos.fx_target:Dispose()
		self.picturing_infos.fx_target = nil
	end
end

function local_class:get_dollar_ui()
	if self.dollar_ui == nil then
		local ui_root_tf = stage.UIRoot.transform
		self.dollar_ui = ui_root_tf:Find('dollar_ui').gameObject
	end

	return self.dollar_ui
end

