function local_class:toggle_monster_battles(enable)
	if enable then
		-- 활성화 시점에는 거의 무조건 배틀 구역과 관련 없는 위치에 있을 것이므로 즉시 활성화해도 될듯
		local monsters = character_manager:GetAllMonsters()
		for i = 0, monsters.Count - 1 do
			local monster = monsters[i]
			if monster.FieldObjectStatsBehaviour.IsDead == false then
				monster.FieldObjectController.DontFight = false
				monster.ActiveState = active_state('visible')
				character_util.spine_set_alpha_fade(monster, 1, 0)
			end
		end
		for _, battle_group in pairs(self.battle_groups) do
			battle_group.IgnoreZoneEvent = false
		end
	else
		coroutine_manager:StartCoroutine(stage.StageGameObject,
				util.cs_generator(self.disable_monster_battles_routine, self))
	end
end

function local_class:disable_monster_battles_routine()
	local monsters = character_manager:GetAllMonsters()
	for i = 0, monsters.Count - 1 do
		local monster = monsters[i]
		if monster.FieldObjectStatsBehaviour.IsDead == false then
			monster.FieldObjectController.DontFight = true
			character_util.spine_set_alpha_fade(monster, 0, 1)
		end
	end

	for _, battle_group in pairs(self.battle_groups) do
		battle_group.IgnoreZoneEvent = true
	end

	wait_for_sec(1)

	for i = 0, monsters.Count - 1 do
		local monster = monsters[i]
		if monster.FieldObjectStatsBehaviour.IsDead == false then
			monster.ActiveState = active_state('disabled')
		end
	end
end

function local_class:custom_drop_item(data, shadow_pos_setting_func)
	local start_pos = data.pos
	local target_pos = data.target
	local top_height = 2
	local speed = 1
	local duration = vector_util.get_x0z(target_pos - start_pos).magnitude / speed

	data.target = nil
	data.lootstate = 'dontfindlooter'
	data.notforinven = true

	local item = drop_item_util.create_item(data)
	local time_passed = 0
	local sprite_tf = item.SpriteTransform
	local shadow_tf = item.ShadowTransform
	local default_quaternion = unity_class.quaternion.AngleAxis(90, unity_class.vector3.right)

	while time_passed < duration do
		local progress = time_passed / duration
		local rot_angle = progress * 360 * 3	-- 3바퀴 돔

		local cur_pos = start_pos * (1 - progress) + target_pos * progress +
				vector(0, math.sin(math.pi * progress) * top_height, 0)
		local cur_rot = default_quaternion * unity_class.quaternion.AngleAxis(rot_angle, unity_class.vector3.forward)

		-- 아이템 포지션 먼저 갱신해줌 (어차피 y가 0으로 나옴)
		item.Position = cur_pos
		sprite_tf.localPosition = vector(0, cur_pos.y + 0.02, 0)
		shadow_tf.localPosition = vector(0, shadow_pos_setting_func(cur_pos), 0)
		sprite_tf.localRotation = cur_rot
		shadow_tf.localRotation = cur_rot

		time_passed = time_passed + unity_class.time.deltaTime
		coroutine.yield()
	end

	return item
end

